    function _matColor(uint256 j) private pure returns (bytes3) {
        uint256 shift = (9 - j) * 24 + 16;
        return bytes3(uint24(uint256(PACK_BASE_MATERIALS >> shift)));
    }

    function var1Pair(
        uint256 i
    ) internal pure returns (bytes3 base, bytes3 shade) {
        if (i >= VAR1_BODY_COLOR_N) revert("idx");
        base = _var1Color(i);
        shade = _var1Color(i + 6);
    }

    function _var1Color(uint256 j) private pure returns (bytes3) {
        if (j < 10) {
            uint256 shift = (9 - j) * 24 + 16;
            return bytes3(uint24(uint256(PACK_VAR1_0 >> shift)));
        } else if (j < 12) {
            uint256 k = j - 10;
            uint256 shift = (1 - k) * 24 + 208;
            return bytes3(uint24(uint256(PACK_VAR1_1 >> shift)));
        } else {
            revert("idx");
        }
    }

    function var2Pair(
        uint256 i
    ) internal pure returns (bytes3 base, bytes3 shade) {
        if (i >= VAR2_BODY_COLOR_N) revert("idx");
        base = _var2Color(i);
        shade = _var2Color(i + 4);
    }

    function _var2Color(uint256 j) private pure returns (bytes3) {
        if (j >= 8) revert("idx");
        uint256 shift = (7 - j) * 24 + 64;
        return bytes3(uint24(uint256(PACK_VAR2_0 >> shift)));
    }

    function _fillPath(
        bytes3 c,
        string memory d,
        string memory id
    ) private pure returns (bytes memory) {
        return
            abi.encodePacked(
                '<path id="',
                id,
                '" style="fill:#',
                HexLib.hex6(c),
                ';" d="',
                d,
                '" />'
            );
    }

    function selectBodyPattern(
        uint256 i
    ) internal pure returns (string memory) {
        if (i >= TOTAL_N) revert("idx");

        if (i < OFF_MAT) return _basePattern(i);
        if (i < OFF_VAR1) return _materialPattern(i);
        if (i < OFF_VAR2) return _var1Pattern(i);
        return _var2Pattern(i);
    }

    function _basePattern(uint256 i) private pure returns (string memory) {
        return string(_fillPath(colorBase(i), D_BODY, "bodyColor"));
    }

    function _materialPattern(uint256 i) private pure returns (string memory) {
        (bytes3 c, bytes3 s) = materialPair(i - OFF_MAT);
        return string(abi.encodePacked(
            _fillPath(c, D_BODY, "bodyColor"),
            _fillPath(s, D_MAT_SHADE, "bodyShade")
        ));
    }

    function _var1Pattern(uint256 i) private pure returns (string memory) {
        (bytes3 c1, bytes3 c2) = var1Pair(i - OFF_VAR1);
        return string(abi.encodePacked(
            _fillPath(c1, D_BODY, "bodyColor"),
            _fillPath(c2, D_VAR1, "bodyPattern")
        ));
    }

    function _var2Pattern(uint256 i) private pure returns (string memory) {
        (bytes3 v1, bytes3 v2) = var2Pair(i - OFF_VAR2);
        return string(abi.encodePacked(
            _fillPath(v1, D_BODY, "bodyColor"),
            _fillPath(v2, D_VAR2, "bodyPattern")
        ));
    }

    function visual(uint256 i) external pure returns (string memory) {
        return
            string(
                abi.encodePacked(
                    '<path style="fill:#000;" d="M 11,7 V 8 H 10 V 9 H 9 v 1 H 8 v 7 H 7 v 1 H 6 v 4 h 1 v 1 h 1 v 2 1 h 1 v 2 h 1 v 1 h 1 v 1 h 9 v -1 h 1 v -1 h 1 v -1 h 1 v -1 h 2 v 1 h 3 v -1 h 1 v -1 h -1 v -1 h -1 v -2 h -1 v -1 h -1 v -1 h -4 v 1 h -1 v 1 h -1 v 1 h -1 v 1 h -2 v -1 h 1 v -1 h 1 v -4 h -1 v -1 h -1 v -2 h 3 v -1 h 1 V 10 H 19 V 9 H 18 V 8 H 17 V 7 Z" />',
                    selectBodyPattern(i),
                    '<path style="fill:#fff;fill-opacity:0.75;" d="m 11,8 v 1 h 6 V 8 Z m 0,1 h -1 v 1 h 1 z m -1,1 H 9 v 7 h 1 z m -3,8 v 1 3 h 1 v -3 h 9 v -1 z m 14,3 v 1 h 4 v -1 z m 0,1 h -1 v 1 h 1 z m -1,1 h -1 v 1 h 1 z m -1,1 h -1 v 1 h 1 z M 9,23 v 3 h 1 v -3 z m 1,3 v 2 h 1 v -2 z m 1,2 v 1 h 1 v -1 z" />'
                )
            );
    }
}

